import java.util.Scanner;

public class ProblemE {

	public static long M = 998244353;

	public static void main(String[] args) {
		// TODO Auto-generated method stub

		Scanner s = new Scanner(System.in);
		long m = s.nextLong();
		long n = s.nextLong();

		long l = s.nextLong();
		long r = s.nextLong();

		long T = m * n;
		long num = r - l + 1;

		long a = exp(num, T);
		//System.out.println(a);
		if(T%2 == 1) {
			System.out.println(a);
		}

		else {
			if(num % 2 == 0)
				System.out.println((a * exp(2, M-2))%M);
			else
				System.out.println(((a + 1)%M * exp(2, M-2))%M);

		}

	}

	public static long exp(long a, long b) {
		long m = M;
		if(b == 0)
			return 1;
		else if(b == 1)
			return a;
		else if(a == 1)
			return 1;
		else if(b%2 == 0)
			return exp((a*a)%m, b/2);
		else
			return (exp((a*a)%m, b/2) * a)%m;
	}

}

